beforeExample:
public class Example {
    public boolean checkAttribute(String value) {
        return Boolean.valueOf(value).booleanValue();
    }
}

afterExample:
public class Example {
    public boolean checkAttribute(String value) {
        return Boolean.parseBoolean(value);
    }
}

